
  CREATE TABLE "MHABERSTOCK"."HM_AT_TEST_LOG" 
   (	"LOG_ID" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1  CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"LOG_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP, 
	"CALLER_LEVEL" VARCHAR2(30 BYTE), 
	"EVENT_TEXT" VARCHAR2(200 BYTE), 
	"SESSION_ID" NUMBER, 
	"LOCAL_TXN_ID" VARCHAR2(50 BYTE), 
	"CURRENT_SCN" NUMBER, 
	"IS_AUTONOMOUS" VARCHAR2(1 BYTE) DEFAULT 'N', 
	"IS_COMMITTED" VARCHAR2(1 BYTE) DEFAULT 'N'
   ) ;
ALTER TABLE "MHABERSTOCK"."HM_AT_TEST_LOG" ADD CHECK (is_autonomous IN ('Y','N')) ENABLE;
ALTER TABLE "MHABERSTOCK"."HM_AT_TEST_LOG" ADD CHECK (is_committed IN ('Y','N')) ENABLE;
ALTER TABLE "MHABERSTOCK"."HM_AT_TEST_LOG" ADD PRIMARY KEY ("LOG_ID")
  USING INDEX  ENABLE;


